parameters.jsCode:
return [{
  json: {
    ...$json,
    PIPEDRIVE_API_TOKEN: "PIPEDRIVE_API_TOKEN_REDACTED",
    QUOTE_WEBHOOK_URL: "https://equipzillaproduccion.app.n8n.cloud/webhook/pipedrive-quote",
    PIPELINE_ID: 6,
    STAGE_ID: 45
  }
}];

// Mapping categoryID → asset_type para Claude
// DEMO: IDs 7 y 8 mapeados a máquinas reales del catálogo GAM 2026.
// Lorenzo/Andrés ampliarán con el resto de IDs reales del formulario web.
const MAP = {
  "7": { asset_type: "Tijera eléctrica 10m", asset_engine: "electrica" },
  "8": { asset_type: "Grupo 60kVA", asset_engine: "diesel" }
  // Ampliar con: { "9": {...}, "10": {...}, ... }
};
return [{ json: { CATEGORY_MAP: MAP } }];

const body = $('Webhook Form Web').first().json.body || $('Webhook Form Web').first().json;
const lead = body.leadData || {};
const articles = Array.isArray(body.articles) ? body.articles : [];

// Email: limpiar markdown [x](mailto:y) → y
let email = String(lead.email || '').trim().toLowerCase();
const md = email.match(/\[([^\]]+)\]\(mailto:[^)]+\)/);
if (md) email = md[1].toLowerCase();
email = email.replace(/^\[/, '').replace(/\]\(mailto:[^)]+\)$/, '').trim().toLowerCase();

// Phone: normalizar a E.164
let phone = String(lead.phone || '').replace(/[^0-9+]/g, '');
if (phone && !phone.startsWith('+')) {
  if (phone.length === 9) phone = '+34' + phone;
  else if (phone.startsWith('00')) phone = '+' + phone.substring(2);
  else if (phone.length >= 10) phone = '+' + phone;
}

const baseLead = {
  name: lead.name || 'Lead web',
  email,
  phone,
  zipcode: String(lead.zipcode || ''),
  profesional: lead.profesional || '',
  utm: lead.utm || '',
  gclid: lead.gclid || '',
  additionalInfo: lead.additionalInfo || {},
  formPageID: body.formPageID || '',
  operation_type: body.operation_type || 'Alquiler',
  globalDateFrom: lead.dateWorkFrom || '',
  globalDateTo: lead.dateWorkTo || ''
};

return [{ json: { ...baseLead, _articles: articles } }];

const lead = $('Extraer datos del form').first().json;
const articles = lead._articles || [];
const personId = $json?.data?.id;
const map = $('📋 Mapping categorías').first().json.CATEGORY_MAP || {};

if (!articles.length) {
  return [{ json: { ...lead, personId, _noArticles: true } }];
}

return articles.map((a, i) => {
  const cat = String(a.categoryID);
  const m = map[cat] || { asset_type: '⚠️ Categoría sin mapear (ID ' + cat + ')', asset_engine: '', needs_manual_mapping: true };
  return {
    json: {
      ...lead,
      _articles: undefined,
      personId,
      _articleIndex: i,
      _articleCount: articles.length,
      categoryID: a.categoryID,
      articleFrom: a.from || lead.globalDateFrom,
      articleTo: a.to || lead.globalDateTo,
      quantity: a.quantity || 1,
      _machine: m
    }
  };
});

